import * as React from "react";
import * as PopoverPrimitive from "@radix-ui/react-popover";
import * as CommandPrimitive from "cmdk";
import { Check, ChevronsUpDown } from "lucide-react";
import { cn } from "@/lib/utils";

const PixelCombobox = PopoverPrimitive.Root;
const PixelComboboxTrigger = PopoverPrimitive.Trigger;
const PixelComboboxAnchor = PopoverPrimitive.Anchor;
const PixelComboboxCancel = PopoverPrimitive.Close;
const PixelComboboxValue = CommandPrimitive.Value;

const PixelComboboxContent = React.forwardRef<
  React.ElementRef<typeof PopoverPrimitive.Content>,
  React.ComponentPropsWithoutRef<typeof PopoverPrimitive.Content>
>(({ className, ...props }, ref) => (
  <PopoverPrimitive.Portal>
    <PopoverPrimitive.Content
      ref={ref}
      data-slot="combobox-content"
      className={cn("z-50 w-[--radix-popover-trigger-width] border-2 border-foreground bg-popover p-0 text-popover-foreground shadow-[var(--pixel-shadow)] outline-none", className)}
      align="start"
      {...props}
    />
  </PopoverPrimitive.Portal>
));
PixelComboboxContent.displayName = "PixelComboboxContent";

const PixelComboboxInput = React.forwardRef<
  React.ElementRef<typeof CommandPrimitive.Command.Input>,
  React.ComponentPropsWithoutRef<typeof CommandPrimitive.Command.Input>
>(({ className, ...props }, ref) => (
  <div data-slot="combobox-input-wrapper" className="flex items-center border-b-2 border-foreground px-3">
    <CommandPrimitive.Command.Input
      ref={ref}
      className={cn("h-10 w-full bg-transparent py-3 text-xs outline-none placeholder:text-muted-foreground font-[family-name:var(--pixel-font)]", className)}
      {...props}
    />
  </div>
));
PixelComboboxInput.displayName = "PixelComboboxInput";

const PixelComboboxList = React.forwardRef<
  React.ElementRef<typeof CommandPrimitive.Command.List>,
  React.ComponentPropsWithoutRef<typeof CommandPrimitive.Command.List>
>(({ className, ...props }, ref) => (
  <CommandPrimitive.Command.List ref={ref} data-slot="combobox-list" className={cn("max-h-[300px] overflow-y-auto overflow-x-hidden", className)} {...props} />
));
PixelComboboxList.displayName = "PixelComboboxList";

const PixelComboboxEmpty = React.forwardRef<
  React.ElementRef<typeof CommandPrimitive.Command.Empty>,
  React.ComponentPropsWithoutRef<typeof CommandPrimitive.Command.Empty>
>(({ className, ...props }, ref) => (
  <CommandPrimitive.Command.Empty ref={ref} data-slot="combobox-empty" className={cn("py-6 text-center text-xs text-muted-foreground", className)} {...props} />
));
PixelComboboxEmpty.displayName = "PixelComboboxEmpty";

const PixelComboboxGroup = CommandPrimitive.Command.Group;

const PixelComboboxItem = React.forwardRef<
  React.ElementRef<typeof CommandPrimitive.Command.Item>,
  React.ComponentPropsWithoutRef<typeof CommandPrimitive.Command.Item>
>(({ className, children, ...props }, ref) => (
  <CommandPrimitive.Command.Item
    ref={ref}
    data-slot="combobox-item"
    className={cn(
      "relative flex cursor-default select-none items-center gap-2 px-2 py-1.5 text-xs font-[family-name:var(--pixel-font)]",
      "data-[selected=true]:bg-accent data-[selected=true]:text-accent-foreground",
      "data-[disabled=true]:pointer-events-none data-[disabled=true]:opacity-50",
      className
    )}
    {...props}
  >
    {children}
    <CommandPrimitive.Command.Item className="ml-auto flex h-3.5 w-3.5 items-center justify-center">
      <Check className="h-4 w-4" strokeWidth={3} />
    </CommandPrimitive.Command.Item>
  </CommandPrimitive.Command.Item>
));
PixelComboboxItem.displayName = "PixelComboboxItem";

const PixelComboboxTriggerStyled = React.forwardRef<
  HTMLButtonElement,
  React.ComponentPropsWithoutRef<"button">
>(({ className, children, ...props }, ref) => (
  <button
    ref={ref}
    data-slot="combobox-trigger"
    className={cn(
      "flex h-10 w-full items-center justify-between border-2 border-foreground bg-transparent px-3 py-2",
      "font-[family-name:var(--pixel-font)] text-xs",
      "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
      "disabled:cursor-not-allowed disabled:opacity-50",
      className
    )}
    {...props}
  >
    {children}
    <ChevronsUpDown className="ml-2 h-4 w-4 shrink-0 opacity-50" strokeWidth={3} />
  </button>
));
PixelComboboxTriggerStyled.displayName = "PixelComboboxTriggerStyled";

export {
  PixelCombobox, PixelComboboxTrigger, PixelComboboxTriggerStyled, PixelComboboxAnchor, PixelComboboxCancel, PixelComboboxValue,
  PixelComboboxInput, PixelComboboxContent, PixelComboboxList, PixelComboboxEmpty, PixelComboboxGroup, PixelComboboxItem,
};
